export type ReportReadinessLevel = 'prep_draft' | 'readiness_assessment' | 'filing_ready';

export type FrameworkReadinessType =
  | 'brsr_filing'
  | 'cbam_registry'
  | 'iso_assurance_prep'
  | 'iso_pcf_prep'
  | 'buyer_pack';

const DEFAULT_LABELS: Record<ReportReadinessLevel, string> = {
  prep_draft: 'Prep draft',
  readiness_assessment: 'Readiness assessment',
  filing_ready: 'Filing ready',
};

const FRAMEWORK_LABELS: Record<string, Partial<Record<ReportReadinessLevel, string>>> = {
  BRSR: {
    prep_draft: 'Prep draft (BRSR)',
    readiness_assessment: 'Readiness assessment (BRSR)',
    filing_ready: 'Submission ready (BRSR Principle 6)',
  },
  CBAM: {
    prep_draft: 'Prep draft (CBAM)',
    readiness_assessment: 'Readiness assessment (CBAM)',
    filing_ready: 'Registry submission ready (CBAM)',
  },
  ISO14064: {
    prep_draft: 'Gap-closure draft (ISO 14064)',
    readiness_assessment: 'Assurance prep ready (ISO 14064)',
    filing_ready: 'Filing ready (ISO 14064 audit pack)',
  },
  ISO14067: {
    prep_draft: 'Product CFP gap-closure draft',
    readiness_assessment: 'PCF disclosure prep ready (ISO 14067)',
    filing_ready: 'Filing ready (ISO 14067 PCF pack)',
  },
};

export const frameworkReadinessLabel = (
  framework: string,
  level?: string,
  fallback?: string | null
): string => {
  if (fallback) {
    return fallback;
  }
  const normalized = String(level || 'prep_draft') as ReportReadinessLevel;
  return FRAMEWORK_LABELS[framework]?.[normalized]
    || DEFAULT_LABELS[normalized]
    || 'Prep draft';
};

export const readinessTypeHint = (readinessType?: string): string | null => {
  switch (readinessType) {
    case 'brsr_filing':
      return 'BRSR Principle 6 pack — SEBI JSON/XBRL unlock when submission-ready gates pass.';
    case 'cbam_registry':
      return 'EU CBAM Transitional Registry submission readiness.';
    case 'iso_assurance_prep':
      return 'ISO 14064 audit pack — filing-ready when score and checks pass.';
    case 'iso_pcf_prep':
      return 'ISO 14067 PCF pack — filing-ready when lifecycle gates pass.';
    case 'buyer_pack':
      return 'Buyer questionnaire pack — not a statutory or certification output.';
    default:
      return null;
  }
};
