import React from 'react';
import { Box, Button, Chip, Stack, Typography } from '@mui/material';
import ArrowForwardIcon from '@mui/icons-material/ArrowForward';
import { Link as RouterLink } from 'react-router-dom';
import {
  disambiguatedRemediationActionLabel,
  estimatedScoreImpactForRemediation,
  remediationActionLabelForBlockedReason,
  remediationLinkForBlockedReason,
} from '../../constants/reportingUxLabels';

type ReadinessRemediationRowProps = {
  reason: string;
  detail?: string;
  priority?: string;
  hubLink?: string | null;
  actionLabel?: string;
  /** Visible wording for the gap. Routing still uses `reason`. */
  reasonLabel?: string;
  /** When true, a repeated destination label includes the gap subject. */
  distinguishAction?: boolean;
  period?: string;
  onResolved?: () => void;
  showScoreImpact?: boolean;
};

const ReadinessRemediationRow: React.FC<ReadinessRemediationRowProps> = ({
  reason,
  detail,
  priority,
  hubLink: hubLinkOverride,
  actionLabel: actionLabelOverride,
  reasonLabel,
  distinguishAction = false,
  showScoreImpact = true,
}) => {
  const hubLink = hubLinkOverride ?? remediationLinkForBlockedReason(reason);
  const baseActionLabel = actionLabelOverride ?? remediationActionLabelForBlockedReason(reason);
  const actionLabel = distinguishAction
    ? disambiguatedRemediationActionLabel(baseActionLabel, reasonLabel || reason)
    : baseActionLabel
  const scoreImpact = estimatedScoreImpactForRemediation(reason);
  const reasonText = reasonLabel || reason;
  const displayReason = detail ? `${reasonText} — ${detail}` : reasonText;

  return (
    <Box
      sx={{
        display: 'flex',
        flexWrap: 'wrap',
        alignItems: 'flex-start',
        justifyContent: 'space-between',
        gap: 1,
        py: 0.75,
      }}
    >
      <Stack direction="row" spacing={1} alignItems="flex-start" sx={{ flex: 1, minWidth: 200 }}>
        {priority ? (
          <Chip
            size="small"
            label={priority}
            color={priority === 'high' ? 'error' : priority === 'medium' ? 'warning' : 'default'}
            variant="outlined"
            sx={{ mt: 0.1 }}
          />
        ) : null}
        <Typography variant="body2" sx={{ flex: 1 }}>
          • {displayReason}
        </Typography>
        {showScoreImpact && scoreImpact ? (
          <Chip size="small" label={`~+${scoreImpact}%`} color="success" variant="outlined" />
        ) : null}
      </Stack>
      {hubLink ? (
        <Button
          size="small"
          variant="contained"
          component={RouterLink}
          to={hubLink}
          endIcon={<ArrowForwardIcon />}
          aria-label={actionLabel !== baseActionLabel ? actionLabel : undefined}
        >
          {actionLabel}
        </Button>
      ) : null}
    </Box>
  );
};

export default ReadinessRemediationRow;
