import React from 'react';
import { Alert, Chip, Stack, Typography } from '@mui/material';
import { frameworkReadinessLabel, readinessTypeHint } from '../../constants/reportReadinessLabels';
import { PRODUCT_SCOPE_STANDARDS } from '../../constants/productScope';
import ReadinessRemediationRow from '../shared/ReadinessRemediationRow';

type ReportFilingReadinessBannerProps = {
  framework: 'BRSR' | 'ISO14064' | 'ISO14067' | 'CBAM';
  readinessLevel?: string | null;
  readinessLabel?: string | null;
  readinessType?: string | null;
  filingDisclaimer?: string | null;
  blockedReasons?: string[];
  warnings?: string[];
  variant?: 'info' | 'warning';
  period?: string;
  onResolved?: () => void;
  /** Disclosure Report only. Adds the gap subject to repeated action labels. */
  distinguishActions?: boolean;
  /** Visible text only. Link matching still uses the original reason. */
  formatReasonDisplay?: (reason: string) => string;
};

const scopeMeta = {
  BRSR: PRODUCT_SCOPE_STANDARDS.brsr,
  ISO14064: PRODUCT_SCOPE_STANDARDS.iso14064,
  ISO14067: PRODUCT_SCOPE_STANDARDS.iso14067,
  CBAM: PRODUCT_SCOPE_STANDARDS.cbam,
};

const ReportFilingReadinessBanner: React.FC<ReportFilingReadinessBannerProps> = ({
  framework,
  readinessLevel,
  readinessLabel,
  readinessType,
  filingDisclaimer,
  blockedReasons = [],
  warnings = [],
  variant = 'info',
  period = 'annual',
  onResolved,
  distinguishActions = false,
  formatReasonDisplay,
}) => {
  const scope = scopeMeta[framework];
  const level = readinessLevel || 'prep_draft';
  const isFilingReady = level === 'filing_ready';
  const isAssurancePrep = level === 'readiness_assessment';
  const advisoryWarnings = warnings.filter(
    (warning) => !blockedReasons.some((reason) => reason === warning)
  );

  return (
    <Alert severity={variant} sx={{ mb: 2 }}>
      <Stack direction="row" spacing={1} flexWrap="wrap" alignItems="center" sx={{ mb: 1 }}>
        <Chip
          size="small"
          label={readinessLabel || frameworkReadinessLabel(framework, level)}
          color={isFilingReady ? 'success' : isAssurancePrep ? 'primary' : 'default'}
        />
        <Chip
          size="small"
          variant="outlined"
          label={isFilingReady ? scope.filingLabel : scope.prepLabel}
        />
        {!isFilingReady && blockedReasons.length > 0 ? (
          <Chip size="small" color="warning" variant="outlined" label={`${blockedReasons.length} step${blockedReasons.length === 1 ? '' : 's'} to filing-ready`} />
        ) : null}
      </Stack>
      <Typography variant="body2" sx={{ mb: 0.5 }}>
        {scope.scope}
      </Typography>
      {readinessTypeHint(readinessType || undefined) ? (
        <Typography variant="caption" color="text.secondary" display="block">
          {readinessTypeHint(readinessType || undefined)}
        </Typography>
      ) : null}
      {filingDisclaimer ? (
        <Typography variant="caption" color="text.secondary" display="block" sx={{ mt: 0.5 }}>
          {filingDisclaimer}
        </Typography>
      ) : null}
      {blockedReasons.length ? (
        <Stack spacing={0.5} sx={{ mt: 1.5 }}>
          <Typography variant="caption" fontWeight={700} color="text.secondary">
            Fix these to raise your {framework} readiness score:
          </Typography>
          {blockedReasons.slice(0, 5).map((reason) => (
            <ReadinessRemediationRow
              key={reason}
              reason={reason}
              reasonLabel={formatReasonDisplay ? formatReasonDisplay(reason) : undefined}
              distinguishAction={distinguishActions}
              period={period}
              onResolved={onResolved}
            />
          ))}
        </Stack>
      ) : null}
      {advisoryWarnings.length ? (
        <Stack spacing={0.5} sx={{ mt: blockedReasons.length ? 1 : 1.5 }}>
          <Typography variant="caption" fontWeight={700} color="text.secondary">
            Recommended before filing:
          </Typography>
          {advisoryWarnings.slice(0, 3).map((warning) => (
            <ReadinessRemediationRow
              key={warning}
              reason={warning}
              reasonLabel={formatReasonDisplay ? formatReasonDisplay(warning) : undefined}
              distinguishAction={distinguishActions}
              period={period}
              onResolved={onResolved}
              showScoreImpact={false}
            />
          ))}
        </Stack>
      ) : null}
    </Alert>
  );
};

export default ReportFilingReadinessBanner;
